WITH session_stats AS (SELECT session_id, AVG(duration_sec) AS avg_duration_sec, SUM(CASE WHEN page = '/cart' THEN duration_sec ELSE 0 END) AS cart_duration_sec FROM web_events WHERE event_type = 'add_to_cart' GROUP BY session_id) SELECT sessions.id, sessions.device, session_stats.avg_duration_sec, session_stats.cart_duration_sec FROM sessions INNER JOIN session_stats ON sessions.id = session_stats.session_id
